#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct lotto_merce {
    char codice[16];
    int quantita;
    double prezzo_unitario;
    bool deperibile;
};

int main(void) {
    const struct lotto_merce riferimento = {
        .codice = "BASE-00", .quantita = 10, .prezzo_unitario = 5.00, .deperibile = false
    };
    struct lotto_merce attivo = {};
    char riga[128], cmd[16], extra = '\0';
    int dep = 0, q = 0, rifiutati = 0;

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%15s %d %lf %d %c", attivo.codice, &attivo.quantita,
               &attivo.prezzo_unitario, &dep, &extra) != 4 ||
        attivo.quantita < 0 || attivo.prezzo_unitario < 0.0 || (dep != 0 && dep != 1)) {
        fprintf(stderr, "Errore: dati lotto non validi.\n");
        return EXIT_FAILURE;
    }
    attivo.deperibile = (dep == 1);

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s %d %c", cmd, &q, &extra) != 2 || q <= 0) {
            fprintf(stderr, "Errore: movimento non valido.\n");
            return EXIT_FAILURE;
        }
        if (strcmp(cmd, "CARICO") == 0) {
            attivo.quantita += q;
        } else if (strcmp(cmd, "SCARICO") == 0) {
            if (q > attivo.quantita) {
                ++rifiutati;
                printf("Scarico rifiutato: disponibili %d\n", attivo.quantita);
            } else {
                attivo.quantita -= q;
            }
        } else {
            fprintf(stderr, "Errore: comando sconosciuto.\n");
            return EXIT_FAILURE;
        }
    }
    double val_att = attivo.quantita * attivo.prezzo_unitario;
    double val_rif = riferimento.quantita * riferimento.prezzo_unitario;
    printf("Lotto: %s (deperibile: %s)\n", attivo.codice, attivo.deperibile ? "si" : "no");
    printf("Quantita finale: %d, prezzo: %.2f euro\n", attivo.quantita, attivo.prezzo_unitario);
    printf("Scarichi rifiutati: %d\n", rifiutati);
    printf("Valore attivo: %.2f euro (diff da %s: %+.2f euro)\n",
           val_att, riferimento.codice, val_att - val_rif);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

typedef enum zona_consegna : int {
    ZONA_URBANA = 0,
    ZONA_NAZIONALE = 1,
    ZONA_ISOLE = 2,
    ZONA_ESTERO = 3
} zona_t;

typedef struct pacco {
    int id;
    zona_t zona;
    double peso_kg;
} pacco_t;

const char *nome_zona(zona_t z);
double calcola_tariffa(pacco_t p);

int main(void) {
    char riga[128], extra = '\0';
    int n = 0, conteggi[4] = {0};
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n, &extra) != 1 || n < 1 || n > 50) {
        fprintf(stderr, "Errore: numero pacchi non valido.\n");
        return EXIT_FAILURE;
    }
    double totale = 0.0;
    for (int i = 0; i < n; ++i) {
        int id = 0, cod_z = 0;
        double peso = 0.0;
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%d %d %lf %c", &id, &cod_z, &peso, &extra) != 3 ||
            id <= 0 || cod_z < 0 || cod_z > 3 || peso <= 0.0) {
            fprintf(stderr, "Errore: dati pacco non validi.\n");
            return EXIT_FAILURE;
        }
        pacco_t p = {.id = id, .zona = (zona_t)cod_z, .peso_kg = peso};
        double costo = calcola_tariffa(p);
        ++conteggi[p.zona];
        totale += costo;
        printf("Pacco #%d [%s, %.2f kg]: %.2f euro\n", p.id, nome_zona(p.zona), p.peso_kg, costo);
    }
    printf("Riepilogo zone -> Urbana: %d, Nazionale: %d, Isole: %d, Estero: %d\n",
           conteggi[0], conteggi[1], conteggi[2], conteggi[3]);
    printf("Incasso totale: %.2f euro\n", totale);
    return EXIT_SUCCESS;
}

const char *nome_zona(zona_t z) {
    switch (z) {
        case ZONA_URBANA: return "Urbana";
        case ZONA_NAZIONALE: return "Nazionale";
        case ZONA_ISOLE: return "Isole";
        default: return "Estero";
    }
}

double calcola_tariffa(pacco_t p) {
    switch (p.zona) {
        case ZONA_URBANA: return 4.00 + 0.50 * p.peso_kg;
        case ZONA_NAZIONALE: return 6.50 + 0.80 * p.peso_kg;
        case ZONA_ISOLE: return 9.00 + 1.10 * p.peso_kg;
        default: return 14.00 + 2.00 * p.peso_kg;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct batteria {
    char seriale[20];
    int capacita_wh;
    int carica_wh;
    int cicli_completi;
    bool in_allarme;
} batteria_t;

bool ricarica_batteria(batteria_t *b, int wh);
bool scarica_batteria(batteria_t *b, int wh);
void stampa_batteria(const batteria_t *b);

int main(void) {
    batteria_t unita = {};
    batteria_t *ptr = &unita;
    char riga[128], cmd[16], extra = '\0';
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%19s %d %d %c", ptr->seriale, &ptr->capacita_wh, &ptr->carica_wh, &extra) != 3 ||
        ptr->capacita_wh <= 0 || ptr->carica_wh < 0 || ptr->carica_wh > ptr->capacita_wh) {
        fprintf(stderr, "Errore: dati batteria non validi.\n");
        return EXIT_FAILURE;
    }
    ptr->in_allarme = (ptr->carica_wh * 10 < ptr->capacita_wh);
    int wh = 0;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) == 1 && strcmp(cmd, "RESET") == 0 &&
            sscanf(riga, "RESET %c", &extra) != 1) {
            ptr->in_allarme = false;
            printf("RESET allarme eseguito\n");
        } else if (sscanf(riga, "%15s %d %c", cmd, &wh, &extra) == 2 && wh > 0) {
            if (strcmp(cmd, "CARICA") == 0) {
                if (ricarica_batteria(ptr, wh)) {
                    printf("CARICA %d: ok (carica=%d Wh, cicli=%d)\n", wh, ptr->carica_wh, ptr->cicli_completi);
                } else { printf("CARICA %d: rifiutata\n", wh); }
            } else if (strcmp(cmd, "SCARICA") == 0) {
                if (scarica_batteria(ptr, wh)) {
                    printf("SCARICA %d: ok (carica=%d Wh, allarme=%d)\n", wh, ptr->carica_wh, ptr->in_allarme);
                } else { printf("SCARICA %d: rifiutata\n", wh); }
            } else { fprintf(stderr, "Errore: comando.\n"); return EXIT_FAILURE; }
        } else { fprintf(stderr, "Errore: formato.\n"); return EXIT_FAILURE; }
    }
    stampa_batteria(ptr);
    return EXIT_SUCCESS;
}

bool ricarica_batteria(batteria_t *b, int wh) {
    if (b == nullptr || b->in_allarme || wh <= 0) { return false; }
    b->carica_wh = (b->carica_wh + wh >= b->capacita_wh) ? b->capacita_wh : (b->carica_wh + wh);
    if (b->carica_wh == b->capacita_wh) { ++b->cicli_completi; }
    return true;
}

bool scarica_batteria(batteria_t *b, int wh) {
    if (b == nullptr || b->in_allarme || wh <= 0 || wh > b->carica_wh) { return false; }
    b->carica_wh -= wh;
    if (b->carica_wh * 10 < b->capacita_wh) { b->in_allarme = true; }
    return true;
}

void stampa_batteria(const batteria_t *b) {
    if (b != nullptr) {
        printf("Batteria %s: %d/%d Wh, cicli=%d, allarme=%d\n",
               b->seriale, b->carica_wh, b->capacita_wh, b->cicli_completi, b->in_allarme);
    }
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct orario { int ore; int minuti; } orario_t;
typedef struct evento { orario_t inizio; int durata_min; char *titolo; } evento_t;

void libera_agenda(evento_t *a, size_t n) {
    for (size_t i = 0; i < n; ++i) { free(a[i].titolo); }
    free(a);
}

int main(void) {
    char riga[128], buf_tit[64], extra = '\0';
    orario_t filtro = {};
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %c", &filtro.ore, &filtro.minuti, &extra) != 2 ||
        filtro.ore < 0 || filtro.ore > 23 || filtro.minuti < 0 || filtro.minuti > 59) {
        fprintf(stderr, "Errore: orario filtro non valido.\n");
        return EXIT_FAILURE;
    }
    evento_t *agenda = nullptr;
    size_t len = 0, cap = 0;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        int h = 0, m = 0, dur = 0;
        if (sscanf(riga, "%d %d %d %63s %c", &h, &m, &dur, buf_tit, &extra) != 4 ||
            h < 0 || h > 23 || m < 0 || m > 59 || dur <= 0) {
            libera_agenda(agenda, len);
            fprintf(stderr, "Errore: evento non valido.\n");
            return EXIT_FAILURE;
        }
        if (len == cap) {
            size_t ncap = (cap == 0) ? 2 : cap * 2;
            evento_t *tmp = realloc(agenda, ncap * sizeof(*agenda));
            if (tmp == nullptr) { libera_agenda(agenda, len); return EXIT_FAILURE; }
            agenda = tmp; cap = ncap;
        }
        char *copia = strdup(buf_tit);
        if (copia == nullptr) { libera_agenda(agenda, len); return EXIT_FAILURE; }
        agenda[len++] = (evento_t){.inizio = {.ore = h, .minuti = m}, .durata_min = dur, .titolo = copia};
    }
    int sel = 0, dur_tot = 0;
    for (size_t i = 0; i < len; ++i) {
        orario_t t = agenda[i].inizio;
        if (t.ore > filtro.ore || (t.ore == filtro.ore && t.minuti >= filtro.minuti)) {
            printf("%02d:%02d (%d min) - %s\n", t.ore, t.minuti, agenda[i].durata_min, agenda[i].titolo);
            ++sel; dur_tot += agenda[i].durata_min;
        }
    }
    printf("Eventi totali: %zu (capacita array: %zu)\n", len, cap);
    printf("Selezionati da %02d:%02d: %d (durata totale: %d min)\n", filtro.ore, filtro.minuti, sel, dur_tot);
    libera_agenda(agenda, len);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct intervallo { int min; int max; } intervallo_t;
typedef struct fascia { intervallo_t lim; char *etichetta; } fascia_t;

intervallo_t crea_intervallo(int a, int b);
bool intervallo_uguale(const intervallo_t *a, const intervallo_t *b);
bool intersezione(intervallo_t a, intervallo_t b, intervallo_t *out);
bool clona_fascia(const fascia_t *orig, fascia_t *dest);

int main(void) {
    char riga[128], nome[32], extra = '\0';
    int a1 = 0, b1 = 0, a2 = 0, b2 = 0, delta = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %31s %c", &a1, &b1, nome, &extra) != 3) { return EXIT_FAILURE; }
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %d %c", &a2, &b2, &delta, &extra) != 3) { return EXIT_FAILURE; }
    fascia_t f1 = {.lim = crea_intervallo(a1, b1), .etichetta = strdup(nome)};
    fascia_t f2 = {};
    if (f1.etichetta == nullptr || !clona_fascia(&f1, &f2)) { free(f1.etichetta); return EXIT_FAILURE; }
    f2.lim.min += delta; f2.lim.max += delta;
    f2.etichetta[0] = '@';
    intervallo_t sec = crea_intervallo(a2, b2), inter = {};
    printf("Originale f1: [%d, %d] etichetta=%s\n", f1.lim.min, f1.lim.max, f1.etichetta);
    printf("Clone mod f2: [%d, %d] etichetta=%s\n", f2.lim.min, f2.lim.max, f2.etichetta);
    printf("Secondo intervallo: [%d, %d] (uguale a f1: %s)\n",
           sec.min, sec.max, intervallo_uguale(&f1.lim, &sec) ? "si" : "no");
    if (intersezione(f1.lim, sec, &inter)) {
        printf("Intersezione f1 e secondo: [%d, %d]\n", inter.min, inter.max);
    } else { printf("Intersezione f1 e secondo: vuota\n"); }
    free(f1.etichetta); free(f2.etichetta);
    return EXIT_SUCCESS;
}

intervallo_t crea_intervallo(int a, int b) {
    return (intervallo_t){.min = (a <= b ? a : b), .max = (a <= b ? b : a)};
}

bool intervallo_uguale(const intervallo_t *a, const intervallo_t *b) {
    return a != nullptr && b != nullptr && a->min == b->min && a->max == b->max;
}

bool intersezione(intervallo_t a, intervallo_t b, intervallo_t *out) {
    int lo = (a.min > b.min) ? a.min : b.min, hi = (a.max < b.max) ? a.max : b.max;
    if (lo > hi) { return false; }
    if (out != nullptr) { *out = (intervallo_t){.min = lo, .max = hi}; }
    return true;
}

bool clona_fascia(const fascia_t *orig, fascia_t *dest) {
    if (orig == nullptr || dest == nullptr) { return false; }
    char *copia = strdup(orig->etichetta);
    if (copia == nullptr) { return false; }
    *dest = (fascia_t){.lim = orig->lim, .etichetta = copia};
    return true;
}
